using DomainCentric.BuildingBlocks.Hexagonal.Ports.In; using DomainCentric.BuildingBlocks.Hexagonal.Ports.Out; using DomainCentric.BuildingBlocks.Ddd.Tactical; using DomainCentric.BuildingBlocks.Application.Transactions;
namespace Acme.Ledger.Application.Read {public sealed record ReadQuery;public sealed record ReadResult(int Value);public interface IReadInputPort:IUseCase<ReadQuery,ReadResult>{} public sealed class ReadUseCase:IReadInputPort{public Task<ReadResult> ExecuteAsync(ReadQuery query,CancellationToken ct=default)=>Task.FromResult(new ReadResult(1));}}
namespace Acme.Ledger.Domain.Model {public readonly record struct EntryId(Guid Value):IId;public sealed class Entry:AggregateRootBase<Entry,EntryId>{public Entry(EntryId id){Id=id;}public override EntryId Id{get;}public void Change(){RegisterEvent(new Changed(Guid.NewGuid(),DateTimeOffset.UtcNow));}}public sealed record Changed(Guid EventId,DateTimeOffset OccurredOn):IDomainEvent;}
namespace Acme.Ledger.Application.Write {public interface IEntryRepository:IRepository<Acme.Ledger.Domain.Model.Entry,Acme.Ledger.Domain.Model.EntryId>{} public sealed record WriteCommand(Guid Id);public sealed record WriteResult(Guid Id);public interface IWriteInputPort:IUseCase<WriteCommand,WriteResult>{}
public sealed class WriteUseCase:IWriteInputPort{private readonly IEntryRepository entries;private readonly IDomainEventPublisher events;private readonly ITransactionBoundary boundary;public WriteUseCase(IEntryRepository entries,IDomainEventPublisher events,ITransactionBoundary boundary){this.entries=entries;this.events=events;this.boundary=boundary;}public async Task<WriteResult> ExecuteAsync(WriteCommand command,CancellationToken ct=default){return await boundary.InTransactionAsync(async token=>{var entry=new Acme.Ledger.Domain.Model.Entry(new Acme.Ledger.Domain.Model.EntryId(command.Id));entry.Change();await entries.SaveAsync(entry,ct);await events.PublishAndClearEventsAsync(entry,ct);return new WriteResult(command.Id);},ct);}}}